const app=document.querySelector('#app'),overlay=document.querySelector('#overlay'),toastEl=document.querySelector('#toast');
// Google may require access to the original image. Keep the interface usable when it cannot be loaded.
document.addEventListener('error', event => {const img=event.target;if(!(img instanceof HTMLImageElement))return;const fallback=fallbackForImage(img.currentSrc||img.src);if(fallback&&!img.dataset.fallbackApplied){img.dataset.fallbackApplied='true';img.src=fallback}}, true);
let filter={category:'',store:'',min:'',max:'',rating:'',free:false,discount:false,stock:false,sort:'relevance',page:1},storeFilter={q:'',category:'',verified:false,sort:'rating'},detail={color:'أسود مطفي',edition:'إصدار برو مع حقيبة السفر',qty:1,tab:'وصف المنتج',image:0},storeTab='جميع المنتجات',presenterOpen=false,workflow=false,tourIndex=-1,submitting=false;
const route=()=>{const [name='home',query='']=location.hash.slice(1).split('?');return {name:name||'home',params:new URLSearchParams(query)}};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s).toLowerCase().replace(/[إأآ]/g,'ا').replace(/ة/g,'ه').replace(/[ً-ْـ]/g,'');
const normalizePhone=s=>String(s||'').replace(/[٠-٩]/g,d=>String(d.charCodeAt(0)-1632)).replace(/[۰-۹]/g,d=>String(d.charCodeAt(0)-1776)).replace(/[\s()-]/g,'');
const goto=(name,params={})=>{location.hash=name+(Object.keys(params).length?'?'+new URLSearchParams(params):'')};
const toast=msg=>{toastEl.className='toast';toastEl.textContent=msg;clearTimeout(toastEl.timer);toastEl.timer=setTimeout(()=>{toastEl.className='';toastEl.textContent=''},2800)};
const dialog=(title,content)=>{overlay.innerHTML=`<div class="modal-backdrop" data-action="close-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button class="icon-btn" data-action="close" aria-label="إغلاق">×</button></div>${content}</section></div>`;overlay.querySelector('button')?.focus()};
const storeName=id=>storeById(id)?.name||'';
const href=(name,params={})=>'#'+name+(Object.keys(params).length?'?'+new URLSearchParams(params):'');
function productCard(p){return `<article class="product-card"><div class="product-image"><a href="${href('product',{id:p.id})}"><img src="${image(p.image)}" alt="${esc(p.name)}" loading="lazy"></a>${p.old?`<span class="badge">خصم ${Math.round((1-p.price/p.old)*100)}%</span>`:''}<button class="fav ${state.favorites.includes(p.id)?'active':''}" data-action="favorite" data-id="${p.id}" aria-label="${state.favorites.includes(p.id)?'إزالة من':'إضافة إلى'} المفضلة">${state.favorites.includes(p.id)?'♥':'♡'}</button></div><div class="product-info"><a class="small muted" href="${href('store',{id:p.store})}">${esc(storeName(p.store))}</a><h3><a href="${href('product',{id:p.id})}">${esc(p.name)}</a></h3><div class="small"><span class="rating">★ ${p.rating}</span> <span class="muted">(${p.reviews})</span></div><div class="price-row"><div><span class="price">${money(p.price)}</span>${p.old?`<span class="old">${money(p.old)}</span>`:''}</div><button class="add" data-action="quick-add" data-id="${p.id}" aria-label="إضافة ${esc(p.name)} إلى السلة">+</button></div></div></article>`}
function storeCard(s){return `<article class="store-card"><a href="${href('store',{id:s.id})}"><img class="store-cover" src="${image(s.cover)}" alt="غلاف ${esc(s.name)}" loading="lazy"></a><div class="store-body"><div class="store-title"><div class="store-logo">${s.name[0]}</div><div><h3>${esc(s.name)} ${s.verified?'<span class="verified">✓</span>':''}</h3><div class="small muted">${esc(s.specialty)} · <span class="rating">★ ${s.rating}</span></div></div></div><p class="muted small">${esc(s.description)}</p><div class="toolbar"><span class="small muted">${products.filter(p=>p.store===s.id).length} منتجات تجريبية · ${s.city}</span><a class="link small" href="${href('store',{id:s.id})}">زيارة المتجر</a></div></div></article>`}
function header(){const count=state.cart.reduce((n,x)=>n+x.qty,0);return `<div class="topbar"><b>جديد</b> &nbsp; توصيل مجاني على طلباتك الأولى من جميع متاجر Surge &nbsp; <a href="#products?discount=1">اكتشف العروض</a></div><header class="header"><div class="wrap head-main"><a class="logo" href="#home">Surge</a><button class="location" data-action="location" aria-label="تغيير موقع التوصيل">${icon('location')}<span><span class="location-label">التوصيل إلى </span><strong>${esc(state.selectedLocation)} ⌄</strong></span></button><form class="search" id="global-search">${icon('search','search-icon')}<input name="q" type="search" aria-label="البحث عن منتجات أو متاجر" placeholder="ابحث عن منتج، متجر أو علامة تجارية..." autocomplete="off" list="suggestions"><datalist id="suggestions">${state.recentSearches.map(q=>`<option value="${esc(q)}">بحث حديث</option>`).join('')}${products.map(p=>`<option value="${esc(p.name)}">`).join('')}${stores.map(s=>`<option value="${esc(s.name)}">`).join('')}</datalist></form><div class="head-actions"><button class="icon-btn" data-action="theme" aria-label="تبديل المظهر">${icon(state.theme==='dark'?'sun':'moon')}</button><button class="icon-btn" data-action="favorites" aria-label="المفضلة">${icon('heart')}</button><button class="icon-btn account" data-action="account" aria-label="حسابي">${icon('user')}</button><a class="icon-btn" href="#cart" aria-label="السلة">${icon('bag')}${count?`<span class="count">${count}</span>`:''}</a><a class="cart-label" href="#cart">السلة</a></div></div><nav class="wrap nav" aria-label="التنقل الرئيسي"><a class="all" href="#products">${icon('menu')} جميع التصنيفات</a><a href="#home">الرئيسية</a><a href="#products">جميع المنتجات</a><a href="#stores">المتاجر</a><a href="#products?discount=1">العروض</a><a href="#products">وصل حديثاً</a><a href="#products?sort=sales">الأكثر مبيعاً</a><span class="nav-note">✓ متاجر محلية وعالمية موثقة</span></nav></header>`}
function footer(){return `<footer><div class="wrap"><div class="footer-grid"><div><div class="logo">Surge</div><p class="muted">منصة تسوق عربية متعددة التجار تجمع أفضل المتاجر المستقلة والعلامات التجارية في تجربة شراء واحدة موثوقة.</p></div><div><b>التسوق</b><a href="#products">جميع المنتجات</a><a href="#stores">دليل المتاجر</a><a href="#products?discount=1">العروض والخصومات</a></div><div><b>خدمة العملاء</b><a href="#" data-action="tracking">تتبع الطلب</a><a href="#" data-action="info">الشحن والتوصيل</a><a href="#" data-action="info">الاستبدال والاسترجاع</a></div><div><b>النشرة البريدية</b><p class="muted">اشترك للحصول على أحدث عروض المتاجر.</p><form id="newsletter" class="actions"><input class="input" type="email" required placeholder="بريدك الإلكتروني" aria-label="البريد الإلكتروني"><button class="btn btn-primary">اشترك</button></form></div></div><div class="footer-bottom">© 2026 Surge Marketplace. جميع الحقوق محفوظة.</div></div></footer><nav class="mobile-nav" aria-label="التنقل للجوال"><a href="#home">${icon("home")}الرئيسية</a><a href="#products">${icon("grid")}التصنيفات</a><a href="#stores">${icon("store")}المتاجر</a><a href="#cart">${icon("bag")}السلة (${state.cart.reduce((n,x)=>n+x.qty,0)})</a><button data-action="account">${icon("user")}حسابي</button></nav>`}
const section=(title,content,link='',subtitle='')=>`<section class="section"><div class="section-head"><div><h2>${title}</h2>${subtitle?`<div class="muted">${subtitle}</div>`:''}</div>${link}</div>${content}</section>`;
const heroSlides=[
 {eyebrow:'عروض الموسم الكبرى — خصومات تصل إلى 40%',title:'كل ما تحتاجه،<br>من متاجرك المفضلة',description:'اكتشف آلاف المنتجات الأصلية من الإلكترونيات والعطور والأزياء والأثاث عبر متاجر موثقة، وتسوق بسهولة في سلة واحدة موحدة.',image:0,alt:'تشكيلة منتجات مختارة من متاجر Surge',href:'#products',cta:'تسوق الآن'},
 {eyebrow:'حملة المنزل العصري',title:'لمسات هادئة تمنح<br>منزلك دفئاً',description:'اكتشف تشكيلة من الإضاءة والديكور والأثاث من متاجرك المفضلة.',image:6,alt:'ديكور منزلي عصري وإضاءة دافئة',href:'#products?category=home',cta:'تصفح الأثاث'},
 {eyebrow:'مختارات عالم التقنية',title:'تقنية ذكية تناسب<br>أسلوب حياتك',description:'تسوق الأجهزة والإكسسوارات المختارة من متاجر متعددة.',image:5,alt:'أجهزة ذكية وإلكترونيات حديثة',href:'#products?category=electronics',cta:'اكتشف الأجهزة'}
];
const categoryPictures={electronics:'demo-tech.jpg',phones:'demo-hero.jpg',fashion:'category-fashion.jpg',beauty:'embedded-ada652e2fc27.png',home:'demo-interior.jpg',food:'embedded-d708f61e5e94.png',sport:'demo-shoes.jpg',kids:'category-kids.jpg'};
let heroIndex=0, lastCarouselInteraction=0, categoryScrollFrame=0, heroWrapTimer=0, heroTextAnimation=null;
function heroSlideMarkup(slide,index,clone=false){const active=!clone&&index===heroIndex;return `<div class="hero-slide${active?' is-active':''}" data-slide="${index}"${clone?' data-clone="true"':''} role="group" aria-roledescription="شريحة" aria-label="${index+1} من ${heroSlides.length}" aria-hidden="${!active}"${active?'':' inert'}><img class="hero-image" src="${image(slide.image)}" alt="${clone?'':slide.alt}"></div>`}
function heroMarkup(){const last=heroSlides.length-1,slide=heroSlides[heroIndex];return `<section class="hero" aria-label="العروض المميزة" aria-roledescription="شريط شرائح"><div class="hero-copy"><div class="eyebrow">${slide.eyebrow}</div><h1>${slide.title}</h1><p>${slide.description}</p><div class="actions"><a class="btn btn-yellow hero-cta" href="${slide.href}">${slide.cta}</a><a class="btn" href="#stores">اكتشف المتاجر</a></div></div><div class="hero-viewport"><div class="hero-track" style="transform:translateX(${(heroIndex+1)*100}%)">${heroSlideMarkup(heroSlides[last],last,true)}${heroSlides.map((item,i)=>heroSlideMarkup(item,i)).join('')}${heroSlideMarkup(heroSlides[0],0,true)}</div></div><div class="hero-controls"><button class="slider-arrow" data-action="hero-prev" aria-label="الشريحة السابقة">${icon('chevronRight')}</button><div class="hero-dots" role="group" aria-label="اختر شريحة">${heroSlides.map((_,i)=>`<button class="hero-dot ${i===heroIndex?'active':''}" data-action="hero-goto" data-id="${i}" aria-label="الشريحة ${i+1}" aria-pressed="${i===heroIndex}"></button>`).join('')}</div><button class="slider-arrow" data-action="hero-next" aria-label="الشريحة التالية">${icon('chevronLeft')}</button></div></section>`}
function updateHeroCopy(hero,index,reduced){
 const copy=hero.querySelector('.hero-copy'),opacity=getComputedStyle(copy).opacity;
 if(heroTextAnimation){heroTextAnimation.onfinish=null;heroTextAnimation.cancel();heroTextAnimation=null}
 const apply=()=>{const slide=heroSlides[index];copy.querySelector('.eyebrow').textContent=slide.eyebrow;copy.querySelector('h1').innerHTML=slide.title;copy.querySelector('p').textContent=slide.description;const link=copy.querySelector('.hero-cta');link.href=slide.href;link.textContent=slide.cta;copy.removeAttribute('inert')};
 if(reduced){apply();return}
 copy.setAttribute('inert','');const fadeOut=copy.animate([{opacity},{opacity:0}],{duration:180,easing:'ease-out',fill:'forwards'});heroTextAnimation=fadeOut;
 fadeOut.onfinish=()=>{if(!copy.isConnected||heroTextAnimation!==fadeOut)return;apply();fadeOut.cancel();const fadeIn=copy.animate([{opacity:0},{opacity:1}],{duration:420,easing:'ease-out'});heroTextAnimation=fadeIn;fadeIn.onfinish=()=>{if(heroTextAnimation===fadeIn)heroTextAnimation=null}};
}
function updateHero(index){
 const hero=document.querySelector('.hero');if(!hero)return;const track=hero.querySelector('.hero-track');
 if(heroWrapTimer){clearTimeout(heroWrapTimer);heroWrapTimer=0;track.style.transition='none';track.style.transform=`translateX(${(heroIndex+1)*100}%)`;void track.offsetWidth;track.style.removeProperty('transition')}
 const total=heroSlides.length,reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 const next=(index%total+total)%total,wrap=index<0||index>=total;
 const position=reduced?next+1:index<0?0:index>=total?total+1:next+1;
 heroIndex=next;track.style.transform=`translateX(${position*100}%)`;
 updateHeroCopy(hero,heroIndex,reduced);
 hero.querySelectorAll('.hero-slide:not([data-clone])').forEach((slide,i)=>{const active=i===heroIndex;slide.classList.toggle('is-active',active);slide.toggleAttribute('inert',!active);slide.setAttribute('aria-hidden',String(!active))});
 hero.querySelectorAll('.hero-dot').forEach((dot,i)=>{dot.classList.toggle('active',i===heroIndex);dot.setAttribute('aria-pressed',String(i===heroIndex))});
 if(wrap&&!reduced)heroWrapTimer=setTimeout(()=>{heroWrapTimer=0;if(!track.isConnected)return;track.style.transition='none';track.style.transform=`translateX(${(heroIndex+1)*100}%)`;void track.offsetWidth;track.style.removeProperty('transition')},900);
}
function cancelCategoryMotion(){cancelAnimationFrame(categoryScrollFrame);categoryScrollFrame=0;const track=document.querySelector('.categories');if(track){track.style.removeProperty('scroll-snap-type');track.style.removeProperty('scroll-behavior')}}
function animateCategoryScroll(track,target){
 cancelCategoryMotion();const max=Math.max(0,track.scrollWidth-track.clientWidth),end=Math.max(-max,Math.min(0,target)),start=track.scrollLeft;
 if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){track.scrollLeft=end;return}
 track.style.scrollSnapType='none';track.style.scrollBehavior='auto';let started;
 function frame(now){if(!track.isConnected){categoryScrollFrame=0;return}if(started===undefined)started=now;const t=Math.min((now-started)/850,1),ease=t<.5?4*t*t*t:1-Math.pow(-2*t+2,3)/2;track.scrollLeft=start+(end-start)*ease;if(t<1)categoryScrollFrame=requestAnimationFrame(frame);else cancelCategoryMotion()}
 categoryScrollFrame=requestAnimationFrame(frame)
}
function moveCategories(direction){const track=document.querySelector('.categories');if(!track)return;const tile=track.querySelector('.category');const distance=(tile?.getBoundingClientRect().width||180)+parseFloat(getComputedStyle(track).columnGap||'0');animateCategoryScroll(track,track.scrollLeft+(direction==='next'?-distance:distance))}
function home(){return `<div class="wrap">${heroMarkup()}${section('تصفح حسب التصنيف',`<div class="categories" role="region" aria-label="تصنيفات المنتجات" tabindex="0">${categories.map(c=>`<a class="category" href="${href('products',{category:c[0]})}"><img src="assets/images/${categoryPictures[c[0]]}" alt="" loading="lazy"><span class="category-label">${c[1]}</span></a>`).join('')}</div>`,`<div class="category-controls"><a class="link" href="#products">جميع التصنيفات</a><button class="slider-arrow" data-action="categories-prev" aria-label="التصنيفات السابقة">${icon('chevronRight')}</button><button class="slider-arrow" data-action="categories-next" aria-label="المزيد من التصنيفات">${icon('chevronLeft')}</button></div>`)}${section('أقوى العروض والخصومات',`<div class="grid">${products.slice(0,4).map(productCard).join('')}</div>`,'<a class="link" href="#products?discount=1">عرض الكل ‹</a>','لفترة محدودة')}<div class="promos"><a href="#products?category=electronics" class="promo"><img src="${image(5)}" alt=""><div><span class="small">محتوى ممول • عالم التقنية</span><h2>ترقية أجهزتك الذكية بأسعار حصرية</h2><p>ضمان رسمي وتوصيل سريع</p><b>اكتشف الأجهزة ‹</b></div></a><a href="#products?category=home" class="promo"><img src="${image(6)}" alt=""><div><span class="small">حملة المنزل العصري</span><h2>لمسات هادئة تمنح منزلك دفئاً</h2><p>تشكيلة من الإضاءة والديكور والأثاث</p><b>تصفح الأثاث ‹</b></div></a></div>${section('منتجات مختارة من جميع المتاجر',`<div class="grid">${products.slice(4).map(productCard).join('')}</div>`,'<a class="link" href="#products">عرض الكل ‹</a>','منتجات متوفرة من متاجر متعددة')}${section('اكتشف متاجرك المفضلة',`<div class="store-grid">${stores.slice(0,3).map(storeCard).join('')}</div>`,'<a class="link" href="#stores">عرض جميع المتاجر ‹</a>','تسوق مباشرة من العلامات التجارية والمتاجر المستقلة')}</div>`}
function filterPanel(){return `<aside class="panel filters" id="filters"><div class="toolbar"><h3>تصفية النتائج</h3><button class="icon-btn mobile-filter" data-action="filters-close" aria-label="إغلاق">×</button></div><div class="filter-group"><b>التصنيفات</b>${categories.map(c=>`<label><input type="radio" name="category" value="${c[0]}" ${filter.category===c[0]?'checked':''}> ${c[1]}</label>`).join('')}</div><div class="filter-group"><b>المتاجر</b>${stores.map(s=>`<label><input type="radio" name="store" value="${s.id}" ${filter.store===s.id?'checked':''}> ${s.name}</label>`).join('')}</div><div class="filter-group"><b>نطاق السعر (ر.ي)</b><div class="actions"><input class="input" type="number" min="0" name="min" placeholder="من" value="${esc(filter.min)}"><input class="input" type="number" min="0" name="max" placeholder="إلى" value="${esc(filter.max)}"></div></div><div class="filter-group"><b>التقييم والتوفر</b><label><input type="checkbox" name="rating" ${filter.rating?'checked':''}> تقييم 4★ فأعلى</label><label><input type="checkbox" name="free" ${filter.free?'checked':''}> توصيل مجاني</label><label><input type="checkbox" name="discount" ${filter.discount?'checked':''}> منتجات مخفضة فقط</label><label><input type="checkbox" name="stock" ${filter.stock?'checked':''}> متوفر في المخزون</label></div><button class="btn btn-block" data-action="clear-filters">مسح جميع التصفيات</button><button class="btn btn-primary btn-block mobile-filter" data-action="filters-close">عرض النتائج</button></aside>`}
function catalog(params){const q=params.get('q')||'';let list=products.filter(p=>{const text=norm([p.name,p.brand,p.description,storeName(p.store),categories.find(c=>c[0]===p.category)?.[1]].join(' '));return (!q||text.includes(norm(q)))&&(!filter.category||p.category===filter.category)&&(!filter.store||p.store===filter.store)&&(!filter.min||p.price>=Number(filter.min)*100)&&(!filter.max||p.price<=Number(filter.max)*100)&&(!filter.rating||p.rating>=4)&&(!filter.free||p.free)&&(!filter.discount||p.old)&&(!filter.stock||p.stock>0)});if(filter.sort==='low')list.sort((a,b)=>a.price-b.price);if(filter.sort==='high')list.sort((a,b)=>b.price-a.price);if(filter.sort==='rating')list.sort((a,b)=>b.rating-a.rating);if(filter.sort==='sales')list.sort((a,b)=>b.reviews-a.reviews);if(filter.sort==='discount')list.sort((a,b)=>(b.old?1-b.price/b.old:0)-(a.old?1-a.price/a.old:0));const count=list.length,pages=Math.ceil(count/6);filter.page=Math.max(1,Math.min(filter.page,pages||1));list=list.slice((filter.page-1)*6,filter.page*6);const chips=[['category',categories.find(c=>c[0]===filter.category)?.[1]],['store',storeName(filter.store)],['min',filter.min&&`من ${filter.min} ر.ي`],['max',filter.max&&`إلى ${filter.max} ر.ي`],['rating',filter.rating&&'تقييم 4★ فأعلى'],['free',filter.free&&'توصيل مجاني'],['discount',filter.discount&&'منتجات مخفضة'],['stock',filter.stock&&'متوفر']].filter(x=>x[1]);return `<div class="wrap"><div class="breadcrumbs"><a href="#home">الرئيسية</a> ‹ جميع المنتجات</div><h1 class="page-title">${q?`نتائج البحث عن «${esc(q)}»`:'جميع المنتجات'}</h1><div class="toolbar"><span class="muted">${count} منتج متوفر</span><button class="btn mobile-filter" data-action="filters-open">☷ تصفية</button><label>ترتيب حسب: <select class="input" id="sort"><option value="relevance">الأكثر صلة</option><option value="sales">الأكثر مبيعاً</option><option value="rating">الأعلى تقييماً</option><option value="low">السعر من الأقل إلى الأعلى</option><option value="high">السعر من الأعلى إلى الأقل</option><option value="discount">أعلى نسبة خصم</option></select></label></div><div class="chips">${chips.map(([k,v])=>`<button class="chip" data-action="remove-filter" data-id="${k}">${esc(v)} ×</button>`).join('')}${chips.length?'<button class="link" data-action="clear-filters">مسح جميع التصفيات</button>':''}</div><div class="layout section">${filterPanel()}<div>${list.length?`<div class="grid catalog-grid">${list.map(productCard).join('')}</div><div class="toolbar">${Array.from({length:pages},(_,i)=>`<button class="btn ${filter.page===i+1?'btn-primary':''}" data-action="page" data-id="${i+1}">${i+1}</button>`).join('')}</div>`:`<div class="empty"><h2>لم نجد نتائج مطابقة لبحثك.</h2><p>جرّب البحث باستخدام كلمات مختلفة أو امسح التصفيات.</p><button class="btn" data-action="clear-filters">مسح التصفيات</button></div>`}</div></div></div>`}
function storesPage(){let list=stores.filter(s=>(!storeFilter.q||norm(s.name+' '+s.specialty).includes(norm(storeFilter.q)))&&(!storeFilter.category||s.category===storeFilter.category)&&(!storeFilter.verified||s.verified));if(storeFilter.sort==='rating')list.sort((a,b)=>b.rating-a.rating);return `<div class="wrap"><div class="breadcrumbs"><a href="#home">الرئيسية</a> ‹ المتاجر</div><h1 class="page-title">اكتشف المتاجر</h1><p class="muted">تسوق من متاجرك المفضلة واكتشف أفضل المنتجات والعروض من متاجر متنوعة.</p><form id="store-search" class="actions"><input class="input" name="q" value="${esc(storeFilter.q)}" placeholder="ابحث عن متجر أو تخصص" aria-label="البحث في المتاجر"><button class="btn">بحث</button></form><div class="toolbar"><div class="chips"><button class="chip" data-action="store-category" data-id="">جميع المتاجر</button>${[['electronics','إلكترونيات'],['beauty','عطور وجمال'],['home','أثاث ومنزل']].map(c=>`<button class="chip" data-action="store-category" data-id="${c[0]}">${c[1]}</button>`).join('')}<button class="chip" data-action="verified">${storeFilter.verified?'✓ ':''}متاجر موثقة</button></div><select class="input" id="store-sort" aria-label="ترتيب المتاجر"><option value="rating">الأعلى تقييماً</option><option value="popular">الأكثر شعبية</option></select></div><div class="section"><h2>المتاجر المميزة <span class="small muted">(${list.length})</span></h2>${list.length?`<div class="store-grid">${list.map(storeCard).join('')}</div>`:'<div class="empty">لم نجد متاجر مطابقة للبحث.</div>'}</div></div>`}
function storePage(params){const s=storeById(params.get('id'));if(!s)return missing('المتجر');let list=products.filter(p=>p.store===s.id);const q=params.get('q')||'';if(q)list=list.filter(p=>norm(p.name+' '+p.description).includes(norm(q)));if(storeTab==='العروض والخصومات')list=list.filter(p=>p.old);let content=storeTab==='عن المتجر'?`<div class="panel"><h2>عن ${s.name}</h2><p>${s.description}</p><p>معلومات المتجر المعروضة تجريبية.</p></div>`:storeTab==='التقييمات'?'<div class="panel"><h2>تقييمات المتجر</h2><p>★ ★ ★ ★ ★</p><p>تجربة تسوق ممتازة ومنتجات مميزة. — تقييم تجريبي</p></div>':`<div class="grid">${list.map(productCard).join('')}</div>${!list.length?'<div class="empty">لا توجد منتجات مطابقة.</div>':''}`;return `<div class="wrap"><div class="breadcrumbs"><a href="#stores">المتاجر</a> ‹ ${s.name}</div><div class="store-hero"><img src="${image(s.cover)}" alt="غلاف ${s.name}"></div><div class="store-intro"><div class="store-title"><div class="store-logo">${s.name[0]}</div><div><h1 class="page-title">${s.name} <span class="verified">${s.verified?'✓':''}</span></h1><span class="rating">★ ${s.rating}</span> <span class="muted"> · ${s.specialty} · ${s.city}</span></div></div><div class="actions"><button class="btn btn-primary" data-action="follow" data-id="${s.id}">${state.followedStores.includes(s.id)?'✓ متابَع':'＋ متابعة المتجر'}</button><button class="btn" data-action="share">مشاركة</button></div></div><nav class="tabs">${['جميع المنتجات','التصنيفات','العروض والخصومات','التقييمات','عن المتجر'].map(t=>`<button data-action="store-tab" data-id="${t}" class="${storeTab===t?'active':''}">${t}</button>`).join('')}</nav><div class="section"><div class="toolbar"><h2>${storeTab==='التصنيفات'?'تصنيفات '+s.name:'منتجات '+s.name}</h2><form id="store-product-search" class="actions"><input class="input" name="q" value="${esc(q)}" placeholder="ابحث في المتجر" aria-label="البحث في المتجر"><button class="btn">بحث</button></form></div>${storeTab==='التصنيفات'?`<div class="chips"><a class="chip" href="${href('products',{store:s.id})}">${s.specialty}</a></div><br>`:''}${content}</div></div>`}
function productPage(params){const p=productById(params.get('id'));if(!p)return missing('المنتج');const s=storeById(p.store),images=p.id==='headphones'?[p.image,14,15,16]:[p.image];const selectedPrice=p.price+(p.variants&&detail.edition==='الإصدار القياسي'?-5000:0);return `<div class="wrap"><div class="breadcrumbs"><a href="#home">الرئيسية</a> ‹ <a href="#products">جميع المنتجات</a> ‹ ${esc(p.name)}</div><div class="product-detail"><div><button class="image-zoom" data-action="zoom" style="border:0;background:none;padding:0;width:100%" aria-label="تكبير الصورة"><img class="detail-image" src="${image(images[detail.image])}" alt="${esc(p.name)}"></button><div class="thumbs">${images.map((n,i)=>`<button data-action="image" data-id="${i}" class="${detail.image===i?'active':''}" aria-label="الصورة ${i+1}"><img src="${image(n)}" alt=""></button>`).join('')}</div></div><div><div class="small muted">العلامة: ${esc(p.brand)} · <a class="link" href="${href('store',{id:s.id})}">${s.name} ✓</a></div><h1>${esc(p.name)}</h1><div><span class="rating">★ ${p.rating}</span> <span class="muted">(${p.reviews} تقييماً) | ✓ متوفر في المخزون</span></div><p><span class="price">${money(selectedPrice)}</span> ${p.old?`<span class="old">${money(p.old)}</span>`:''}</p><p class="muted">${esc(p.description)}</p>${p.variants?`<b>اللون: ${detail.color}</b><div class="variant">${['أسود مطفي','أخضر غابات','فضي'].map(c=>`<button class="btn ${detail.color===c?'active':''}" data-action="color" data-id="${c}" ${c==='فضي'?'disabled':''}>${c}${c==='فضي'?' — غير متوفر':''}</button>`).join('')}</div><b>الإصدار:</b><div class="variant">${['إصدار برو مع حقيبة السفر','الإصدار القياسي'].map(c=>`<button class="btn ${detail.edition===c?'active':''}" data-action="edition" data-id="${c}">${c}</button>`).join('')}</div>`:''}<div class="actions"><div class="quantity"><button data-action="detail-minus" aria-label="تقليل الكمية">−</button><span>${detail.qty}</span><button data-action="detail-plus" aria-label="زيادة الكمية">+</button></div><button class="btn btn-primary" data-action="add-detail" data-id="${p.id}">أضف إلى السلة</button><button class="btn btn-yellow" data-action="buy" data-id="${p.id}">اشتر الآن</button></div><div class="actions" style="margin-top:12px"><button class="btn" data-action="favorite" data-id="${p.id}">${state.favorites.includes(p.id)?'♥ في المفضلة':'♡ أضف إلى المفضلة'}</button><button class="btn" data-action="share">مشاركة المنتج</button></div><div class="benefits"><div class="benefit">🚚 توصيل ${p.free?'مجاني':'حسب المتجر'} إلى ${esc(state.selectedLocation)}</div><div class="benefit">✓ استرجاع مرن خلال 14 يوماً</div><div class="benefit">♧ ضمان الوكيل</div><div class="benefit">▣ خيارات دفع متعددة</div></div><p><a class="link" href="${href('store',{id:s.id})}">زيارة متجر ${s.name} ‹</a></p></div></div><div class="section"><nav class="tabs">${['وصف المنتج','المواصفات','التقييمات والمراجعات','الشحن والاسترجاع'].map(t=>`<button data-action="product-tab" data-id="${t}" class="${detail.tab===t?'active':''}">${t}</button>`).join('')}</nav><div class="panel">${detail.tab==='وصف المنتج'?`<h3>تفاصيل المنتج</h3><p>${esc(p.description)}</p>`:detail.tab==='المواصفات'?`<p>العلامة: ${esc(p.brand)}</p><p>المعرف: <bdi>SRG-${p.id.toUpperCase()}</bdi></p>${p.variants?'<p>البطارية: 50 ساعة · الاتصال: Bluetooth / USB-C</p>':''}`:detail.tab==='التقييمات والمراجعات'?`<p class="rating">★ ${p.rating} (${p.reviews})</p><p>منتج ممتاز وتجربة تسوق مريحة. — تقييم تجريبي</p>`:'<p>يتم شحن الطلب من المتجر. تفاصيل الشحن والاسترجاع المعروضة للتوضيح التجريبي.</p>'}</div></div>${section('منتجات أخرى قد تعجبك',`<div class="grid">${products.filter(x=>x.id!==p.id).slice(0,4).map(productCard).join('')}</div>`,'<a class="link" href="#products">عرض الكل ‹</a>')}</div>`}
function missing(type){return `<div class="wrap empty"><h2>لم نعثر على ${type}</h2><p>قد يكون الرابط غير صحيح.</p><a class="btn btn-primary" href="#products">تصفح المنتجات</a></div>`}
function summary(button=true){const t=totals();return `<aside class="panel summary"><h2>ملخص الطلب</h2><div class="summary-line"><span>إجمالي المنتجات</span><b>${money(t.subtotal)}</b></div><div class="summary-line"><span>الخصومات</span><b>− ${money(t.discount)}</b></div><div class="summary-line"><span>تكلفة التوصيل</span><b>${money(t.shipping)}</b></div><div class="summary-line summary-total"><span>الإجمالي النهائي</span><span>${money(t.total)}</span></div>${button?'<a class="btn btn-yellow btn-block" href="#checkout">إتمام الطلب</a>':''}<p class="small muted">الأسعار وعمليات الدفع في هذه النسخة تجريبية.</p></aside>`}
function cartPage(){if(!state.cart.length)return `<div class="wrap empty"><h1>سلة التسوق فارغة</h1><p>اكتشف المنتجات وأضف ما يعجبك إلى سلتك.</p><a class="btn btn-primary" href="#products">تصفح المنتجات</a></div>`;const ids=[...new Set(state.cart.map(x=>productById(x.id).store))];return `<div class="wrap section"><div class="section-head"><h1>سلة التسوق (${state.cart.reduce((n,x)=>n+x.qty,0)} منتجات من ${ids.length} متاجر)</h1><a class="link" href="#products">متابعة التسوق</a></div><div class="cart-layout"><div>${ids.map(id=>`<div class="panel cart-group"><h3><a href="${href('store',{id})}">${storeName(id)} ✓</a></h3>${state.cart.map((x,i)=>({x,i})).filter(({x})=>productById(x.id).store===id).map(({x,i})=>{const p=productById(x.id);return `<div class="cart-item"><a href="${href('product',{id:p.id})}"><img src="${image(p.image)}" alt="${esc(p.name)}"></a><div><b><a href="${href('product',{id:p.id})}">${esc(p.name)}</a></b><div class="small muted">${esc([x.color,x.edition].filter(Boolean).join(' • '))}</div><div class="quantity"><button data-action="cart-minus" data-id="${i}">−</button><span>${x.qty}</span><button data-action="cart-plus" data-id="${i}">+</button></div> <button class="icon-btn" data-action="cart-remove" data-id="${i}" aria-label="حذف المنتج">×</button></div><b class="cart-amount">${money(price(x)*x.qty)}</b></div>`}).join('')}</div>`).join('')}<div class="panel"><form id="coupon" class="actions"><input class="input" name="code" placeholder="كود الخصم" aria-label="كود الخصم" value="${esc(state.appliedCoupon||'')}"><button class="btn">تطبيق</button>${state.appliedCoupon?'<button type="button" class="btn" data-action="remove-coupon">إزالة الكود</button>':''}</form></div></div>${summary()}</div></div>`}
function checkout(){if(!state.cart.length)return `<div class="wrap empty"><h1>سلة التسوق فارغة</h1><a class="btn btn-primary" href="#products">تصفح المنتجات</a></div>`;let draft={};try{draft=JSON.parse(sessionStorage.getItem('surge.checkout')||'{}')}catch{}return `<div class="wrap section"><h1>إتمام الطلب</h1><p class="muted">إتمام آمن تجريبي · لا يتم تحصيل أي مبالغ</p><div class="checkout-layout"><form id="checkout-form" novalidate><div class="panel"><h2>١. عنوان التوصيل ومعلومات التواصل</h2><label class="field">الاسم الكامل<input class="input" name="name" value="${esc(draft.name||'')}" autocomplete="name"><span class="error" data-error="name"></span></label><label class="field">رقم الجوال<input class="input" name="phone" value="${esc(draft.phone||'')}" placeholder="مثال: ٧٧١٢٣٤٥٦٧" inputmode="tel" autocomplete="tel"><span class="error" data-error="phone"></span></label><label class="field">العنوان<input class="input" name="address" value="${esc(draft.address||'')}" autocomplete="street-address"><span class="error" data-error="address"></span></label></div><div class="panel section"><h2>٢. طريقة الدفع</h2>${['البطاقة البنكية','المحفظة الإلكترونية','الدفع عند الاستلام'].map((x,i)=>`<label class="payment"><input type="radio" name="payment" value="${x}" ${draft.payment===x||(!draft.payment&&i===0)?'checked':''}> ${x} <span class="muted small">محاكاة فقط</span></label>`).join('')}<span class="error" data-error="payment"></span></div><div class="panel"><h2>مراجعة الطلب</h2>${state.cart.map(x=>`<p>${esc(productById(x.id).name)} × ${x.qty} <span class="muted">· ${storeName(productById(x.id).store)} ${esc(x.color)} ${esc(x.edition)}</span> <b>${money(price(x)*x.qty)}</b></p>`).join('')}</div><p class="error" id="checkout-error"></p><button class="btn btn-yellow btn-block" type="submit" ${submitting?'disabled':''}>${submitting?'جارٍ تأكيد الطلب...':`تأكيد الطلب التجريبي · ${money(totals().total)}`}</button></form>${summary(false)}</div></div>`}
function success(params){const o=state.orders.find(x=>x.id===params.get('id'));if(!o)return missing('الطلب');return `<div class="wrap section"><div class="panel"><h1>✓ تم تأكيد طلبك بنجاح</h1><p>هذا الطلب جزء من النسخة التجريبية، ولم تُنفّذ أي عملية دفع حقيقية.</p><p>رقم الطلب: <bdi>${esc(o.id)}</bdi> · ${esc(o.date)}</p><p>طريقة الدفع: ${esc(o.payment)} · الحالة: تم تأكيد الطلب التجريبي</p><h2>تفاصيل الطلب</h2>${o.items.map(x=>`<p>${esc(productById(x.id)?.name||x.id)} × ${x.qty} · ${esc(storeName(productById(x.id)?.store))} · ${esc(x.color)} ${esc(x.edition)}</p>`).join('')}<h3>الإجمالي: ${money(o.total)}</h3><a class="btn btn-primary" href="#products">متابعة التسوق</a></div></div>`}
function presenter(){if(!new URLSearchParams(location.search).has('demo'))return '';return `<div class="presenter">${presenterOpen?`<div class="presenter-panel"><div class="toolbar"><b>أدوات العرض التجريبي</b><button class="icon-btn" data-action="presenter">×</button></div><label>سيناريو العرض <select id="scenario" class="input"><option value="default">اختر سيناريو</option><option value="new">تجربة مستخدم جديد</option><option value="single">شراء منتج واحد</option><option value="multi">شراء من عدة متاجر</option><option value="discount">تجربة الخصومات</option><option value="stock">تجربة نفاد المخزون</option><option value="failure">فشل الدفع وإعادة المحاولة</option><option value="success">تجربة الطلب الناجح</option></select></label><div><button class="btn" data-action="demo-fill">تعبئة سلة تجريبية</button><button class="btn" data-action="demo-empty">إفراغ السلة</button><button class="btn" data-action="demo-address">تعبئة بيانات التوصيل</button><button class="btn" data-action="demo-failure">${state.paymentFailure?'محاكاة نجاح الدفع':'محاكاة فشل الدفع'}</button><button class="btn" data-action="demo-no-results">محاكاة عدم وجود نتائج</button><button class="btn" data-action="theme">تبديل المظهر</button><button class="btn" data-action="workflow">${workflow?'إخفاء':'عرض'} استعراض العمليات</button><button class="btn" data-action="tour">جولة تعريفية</button><button class="btn" data-action="demo-reset">إعادة ضبط التجربة</button><a class="btn" href="#home">الرئيسية</a></div>${workflow?`<h3>استعراض العمليات <span class="small">(محاكاة)</span></h3><div class="event-log">${state.events.slice().reverse().map(x=>`<p>${esc(x.time)} · ${esc(x.message)}</p>`).join('')||'تظهر الأحداث بعد التفاعل مع الموقع.'}</div><button class="btn" data-action="clear-log">مسح الأحداث</button>`:''}</div>`:`<button class="btn btn-primary" data-action="presenter">أدوات العرض</button>`}</div>`}
function render(){document.documentElement.dataset.theme=state.theme;const r=route();const pages={home,products:()=>catalog(r.params),stores:storesPage,store:()=>storePage(r.params),product:()=>productPage(r.params),cart:cartPage,checkout,success:()=>success(r.params)};app.innerHTML=header()+(pages[r.name]||home)()+footer()+presenter();const sort=document.querySelector('#sort');if(sort)sort.value=filter.sort;const ss=document.querySelector('#store-sort');if(ss)ss.value=storeFilter.sort}
function addProduct(id,qty=1,color='',edition=''){const existingStores=new Set(state.cart.map(x=>productById(x.id).store));if(add(id,qty,color,edition)){log('تم التحقق من توفر المنتج.','تم تحديد المتجر المرتبط بالمنتج.',...(existingStores.size&&!existingStores.has(productById(id).store)?['تم التعرف على متجر مختلف وإنشاء مجموعة جديدة داخل السلة.']:[]),'تم تسجيل المنتج والمتغير المحدد وتحديث إجمالي السلة.');toast('تمت إضافة المنتج إلى السلة.');return true}toast('الكمية المطلوبة غير متوفرة.');return false}
function showFavorites(){dialog('المنتجات المفضلة',state.favorites.length?`<div class="grid" style="grid-template-columns:repeat(2,1fr)">${state.favorites.map(productById).filter(Boolean).map(productCard).join('')}</div>`:'<div class="empty"><p>لا توجد منتجات في المفضلة بعد.</p><a class="btn btn-primary" href="#products" data-action="close">تصفح المنتجات</a></div>')}
function tour(){const steps=[['اكتشاف المنتجات','تصفح المنتجات والعروض من متاجر متعددة.','a[href="#products"]'],['البحث والتصفية','استخدم البحث والتصفيات للوصول إلى ما يناسبك.','#global-search'],['استكشاف المتاجر','اكتشف المتاجر وتعرف على منتجات كل تاجر.','a[href="#stores"]'],['اختيار تفاصيل المنتج','افتح منتجاً لاختيار اللون والإصدار والكمية المتاحة.','.product-card a'],['إضافة المنتجات إلى السلة','أضف المنتجات التي اخترتها إلى سلة واحدة.','.product-card .add'],['التسوق من عدة متاجر','تظهر المنتجات في السلة مجمعة بحسب المتجر.','a[href="#cart"]'],['إتمام الطلب','راجع السلة وأكمل عملية شراء تجريبية.','a[href="#cart"]']];const [title,description,selector]=steps[tourIndex];document.querySelectorAll('.tour-highlight').forEach(x=>x.classList.remove('tour-highlight'));let target=[...document.querySelectorAll(selector)].find(x=>x.getClientRects().length);target?.classList.add('tour-highlight');target?.scrollIntoView({block:'nearest'});overlay.innerHTML=`<section class="tour-panel" role="region" aria-label="جولة تعريفية"><b>جولة تعريفية · ${tourIndex+1} / ${steps.length}</b><h3>${title}</h3><p>${description}</p><div class="actions"><button class="btn" data-action="tour-prev" ${tourIndex===0?'disabled':''}>السابق</button><button class="btn btn-primary" data-action="tour-next">${tourIndex===steps.length-1?'إنهاء':'التالي'}</button><button class="btn" data-action="close">تخطي</button></div></section>`}
function initializeRoute(){const r=route();if(r.name==='products'){filter.category=r.params.get('category')||'';filter.store=r.params.get('store')||'';filter.discount=r.params.get('discount')==='1';filter.sort=r.params.get('sort')||'relevance';filter.page=1}if(r.name==='product')detail={color:'أسود مطفي',edition:'إصدار برو مع حقيبة السفر',qty:1,tab:'وصف المنتج',image:0};if(r.name==='store')storeTab='جميع المنتجات';overlay.innerHTML='';render();window.scrollTo(0,0)}
window.addEventListener('hashchange',initializeRoute);window.addEventListener('storage',e=>{if(e.key==='surge.demo.v1')location.reload()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){overlay.innerHTML='';document.querySelector('#filters')?.classList.remove('open')}});
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;if(el.tagName==='A'&&el.getAttribute('href')==='#')e.preventDefault();
 switch(action){
 case 'hero-prev':lastCarouselInteraction=Date.now();updateHero(heroIndex-1);break;
 case 'hero-next':lastCarouselInteraction=Date.now();updateHero(heroIndex+1);break;
 case 'hero-goto':lastCarouselInteraction=Date.now();updateHero(Number(id));break;
 case 'categories-prev':lastCarouselInteraction=Date.now();moveCategories('prev');break;
 case 'categories-next':lastCarouselInteraction=Date.now();moveCategories('next');break;
 case 'theme':state.theme=state.theme==='light'?'dark':'light';save();render();break;
 case 'location':dialog('موقع التوصيل',`<p>اختر المدينة التي تريد التوصيل إليها.</p><div class="actions">${['المكلا','سيئون','عدن','صنعاء'].map(x=>`<button class="btn" data-action="choose-location" data-id="${x}">${x}</button>`).join('')}</div>`);break;
 case 'choose-location':state.selectedLocation=id;save();overlay.innerHTML='';render();toast('تم تحديث موقع التوصيل.');break;
 case 'favorite':state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();toast(state.favorites.includes(id)?'تمت إضافة المنتج إلى المفضلة.':'تمت إزالة المنتج من المفضلة.');if(overlay.innerHTML)showFavorites();render();break;
 case 'favorites':showFavorites();break;
 case 'quick-add':{const p=productById(id);if(p.variants){overlay.innerHTML='';goto('product',{id});toast('اختر تفاصيل المنتج قبل إضافته.')}else{addProduct(id);render()}break}
 case 'follow':state.followedStores=state.followedStores.includes(id)?state.followedStores.filter(x=>x!==id):[...state.followedStores,id];save();render();toast('تم تحديث متابعة المتجر.');break;
 case 'share':try{await navigator.clipboard.writeText(location.href);toast('تم نسخ الرابط.')}catch{dialog('مشاركة الرابط',`<input class="input" value="${esc(location.href)}" readonly aria-label="رابط الصفحة">`)}break;
 case 'close':overlay.innerHTML='';document.querySelectorAll('.tour-highlight').forEach(x=>x.classList.remove('tour-highlight'));break;case 'close-backdrop':if(e.target===el)overlay.innerHTML='';break;
 case 'account':dialog('حسابي','<p>هذه نسخة تجريبية. إدارة الحساب وتسجيل الدخول خارج نطاق العرض.</p><button class="btn" data-action="tracking">عرض آخر طلب تجريبي</button>');break;
 case 'tracking':{const o=state.orders.at(-1);dialog('تتبع الطلب',o?`<p>آخر طلب تجريبي: <bdi>${esc(o.id)}</bdi></p><p>الحالة: تم تأكيد الطلب التجريبي.</p><a class="btn" href="${href('success',{id:o.id})}" data-action="close">عرض التفاصيل</a>`:'<p>لا توجد طلبات تجريبية بعد.</p>');break}
 case 'info':dialog('معلومات تجريبية','<p>هذه المعلومات خارج نطاق النسخة التجريبية. لم يتم ربط خدمات الشحن أو الدعم.</p>');break;
 case 'filters-open':document.querySelector('#filters')?.classList.add('open');break;case 'filters-close':document.querySelector('#filters')?.classList.remove('open');break;
 case 'clear-filters':filter={category:'',store:'',min:'',max:'',rating:'',free:false,discount:false,stock:false,sort:'relevance',page:1};if(route().params.toString())goto('products');else render();break;
 case 'remove-filter':filter[id]=typeof filter[id]==='boolean'?false:'';filter.page=1;render();break;case 'page':filter.page=Number(id);render();window.scrollTo(0,0);break;
 case 'store-category':storeFilter.category=id;render();break;case 'verified':storeFilter.verified=!storeFilter.verified;render();break;case 'store-tab':storeTab=id;render();break;
 case 'color':detail.color=id;render();break;case 'edition':detail.edition=id;render();break;case 'image':detail.image=Number(id);render();break;
 case 'zoom':{const p=productById(route().params.get('id'));const gallery=p.id==='headphones'?[p.image,14,15,16]:[p.image];dialog('صورة المنتج',`<img src="${image(gallery[detail.image])}" alt="${esc(p.name)}" style="width:100%">`);break}
 case 'detail-minus':detail.qty=Math.max(1,detail.qty-1);render();break;case 'detail-plus':{const p=productById(route().params.get('id'));if(detail.qty<p.stock)detail.qty++;else toast('الكمية المطلوبة غير متوفرة.');render();break}
 case 'product-tab':detail.tab=id;render();break;
 case 'add-detail':case 'buy':{const p=productById(id);if(addProduct(id,detail.qty,p.variants?detail.color:'',p.variants?detail.edition:'')){if(action==='buy')goto('checkout');else render()}break}
 case 'cart-minus':if(state.cart[id].qty>1)state.cart[id].qty--;else state.cart.splice(id,1);save();render();toast('تم تحديث الكمية.');break;
 case 'cart-plus':if(state.cart[id].qty<productById(state.cart[id].id).stock){state.cart[id].qty++;save();render();toast('تم تحديث الكمية.')}else toast('الكمية المطلوبة غير متوفرة.');break;
 case 'cart-remove':state.cart.splice(id,1);if(!state.cart.length)state.appliedCoupon=null;save();render();toast('تم حذف المنتج من السلة.');break;
 case 'remove-coupon':state.appliedCoupon=null;save();render();toast('تمت إزالة الكود.');break;
 case 'presenter':presenterOpen=!presenterOpen;render();break;case 'workflow':workflow=!workflow;render();break;case 'clear-log':state.events=[];save();render();break;
 case 'demo-fill':state.cart=[];add('headphones',1,'أسود مطفي','إصدار برو مع حقيبة السفر');add('oud',1);render();toast('تمت تعبئة السلة التجريبية.');break;
 case 'demo-empty':state.cart=[];state.appliedCoupon=null;save();render();toast('تم إفراغ السلة.');break;
 case 'demo-address':sessionStorage.setItem('surge.checkout',JSON.stringify({name:'أحمد التجريبي',phone:'771234567',address:'المكلا، حي السلام، شارع تجريبي',payment:'البطاقة البنكية'}));render();toast('تمت تعبئة بيانات توصيل تجريبية.');break;
 case 'demo-failure':state.paymentFailure=!state.paymentFailure;save();render();toast(state.paymentFailure?'ستفشل محاولة الدفع التالية.':'تم تفعيل نجاح الدفع.');break;
 case 'demo-no-results':goto('products',{q:'منتج غير موجود تجريبياً'});break;
 case 'demo-reset':dialog('إعادة ضبط التجربة','<p>سيتم حذف بيانات Surge التجريبية المحفوظة في هذا المتصفح.</p><div class="actions"><button class="btn btn-primary" data-action="confirm-reset">تأكيد إعادة الضبط</button><button class="btn" data-action="close">إلغاء</button></div>');break;
 case 'confirm-reset':reset();sessionStorage.removeItem('surge.checkout');overlay.innerHTML='';goto('home');render();toast('تمت إعادة ضبط التجربة.');break;
 case 'tour':tourIndex=0;tour();break;case 'tour-prev':tourIndex=Math.max(0,tourIndex-1);tour();break;case 'tour-next':if(++tourIndex>=7){overlay.innerHTML='';document.querySelectorAll('.tour-highlight').forEach(x=>x.classList.remove('tour-highlight'));tourIndex=-1}else tour();break;
 }
});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='sort'){filter.sort=el.value;filter.page=1;render()}else if(el.id==='store-sort'){storeFilter.sort=el.value;render()}else if(el.closest('#filters')&&el.name){filter[el.name]=el.type==='checkbox'?el.checked:el.value;filter.page=1;const open=el.closest('#filters').classList.contains('open');render();if(open)document.querySelector('#filters')?.classList.add('open')}else if(el.id==='scenario'){const scenario=el.value;state.demoScenario=scenario;state.cart=[];state.appliedCoupon=null;state.paymentFailure=scenario==='failure';if(['single','multi','discount','failure','success','stock'].includes(scenario))add('headphones',scenario==='stock'?10:1,'أسود مطفي','إصدار برو مع حقيبة السفر');if(['multi','discount'].includes(scenario))add('oud',1);if(scenario==='discount')state.appliedCoupon='SURGE10';save();render();toast('تم تفعيل السيناريو التجريبي.')}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,data=new FormData(f);if(f.id==='global-search'){const q=String(data.get('q')||'').trim();if(q){state.recentSearches=[q,...state.recentSearches.filter(x=>x!==q)].slice(0,5);save();goto('products',{q})}}else if(f.id==='newsletter'){toast('تم تسجيل الاشتراك التجريبي بنجاح.');f.reset()}else if(f.id==='store-search'){storeFilter.q=String(data.get('q')||'').trim();render()}else if(f.id==='store-product-search'){goto('store',{id:route().params.get('id'),q:String(data.get('q')||'').trim()})}else if(f.id==='coupon'){const code=String(data.get('code')||'').trim().toUpperCase();if(code==='SURGE10'){if(state.appliedCoupon===code)toast('الكود مطبق بالفعل.');else{state.appliedCoupon=code;save();log('تم التحقق من الكود التجريبي.','تم احتساب الخصم وتحديث المبلغ المستحق.');render();toast('تم تطبيق كود الخصم بنجاح.')}}else toast('كود الخصم غير صالح.')}else if(f.id==='checkout-form'){if(submitting)return;const d=Object.fromEntries(data);const errors={};if(!d.name||d.name.trim().length<3)errors.name='يرجى إدخال الاسم الكامل.';if(!/^(?:(?:\+967|00967|967))?7\d{8}$/.test(normalizePhone(d.phone)))errors.phone='يرجى إدخال رقم جوال يمني صالح من ٩ أرقام.';if(!d.address||d.address.trim().length<8)errors.address='يرجى إدخال عنوان التوصيل كاملاً.';if(!d.payment)errors.payment='يرجى اختيار طريقة الدفع.';f.querySelectorAll('[data-error]').forEach(x=>x.textContent=errors[x.dataset.error]||'');if(Object.keys(errors).length)return;if(!state.cart.length){document.querySelector('#checkout-error').textContent='السلة فارغة.';return}submitting=true;const button=f.querySelector('[type=submit]');button.disabled=true;button.textContent='جارٍ تأكيد الطلب...';setTimeout(()=>{submitting=false;if(state.paymentFailure){state.paymentFailure=false;save();button.disabled=false;button.textContent='إعادة المحاولة';document.querySelector('#checkout-error').textContent='تعذرت محاكاة الدفع. لم يتم خصم أي مبلغ، ويمكنك إعادة المحاولة.';return}const t=totals();const order={id:'SRG-'+Date.now().toString(36).toUpperCase(),date:new Date().toLocaleDateString('ar-YE'),payment:d.payment,items:structuredClone(state.cart),total:t.total};state.orders.push(order);state.cart=[];state.appliedCoupon=null;save();sessionStorage.removeItem('surge.checkout');log('تم التحقق من معلومات التوصيل والمنتجات.','تمت محاكاة الدفع وإنشاء الطلب التجريبي.','تم تنظيم المنتجات بحسب المتاجر وعرض التأكيد.');goto('success',{id:order.id});toast('تم تأكيد الطلب التجريبي.')},600)}});
document.addEventListener('input',e=>{if(e.target.closest('#checkout-form')){const f=e.target.form;const d=Object.fromEntries(new FormData(f));try{sessionStorage.setItem('surge.checkout',JSON.stringify(d))}catch{}}});
initializeRoute();
// Stop automatic movement when the page is hidden, being interacted with, or reduced motion is preferred.
document.addEventListener('pointerdown',e=>{if(e.target.closest('.hero,.categories'))lastCarouselInteraction=Date.now();if(e.target.closest('.categories'))cancelCategoryMotion()});
document.addEventListener('wheel',e=>{if(e.target.closest('.categories')){lastCarouselInteraction=Date.now();cancelCategoryMotion()}},{passive:true});
let heroTouchStart=null;
document.addEventListener('touchstart',e=>{if(e.target.closest('.hero')&&!e.target.closest('.hero-controls')&&e.touches.length===1){heroTouchStart={x:e.touches[0].clientX,y:e.touches[0].clientY};lastCarouselInteraction=Date.now()}},{passive:true});
document.addEventListener('touchend',e=>{if(!heroTouchStart)return;const touch=e.changedTouches[0];const dx=touch.clientX-heroTouchStart.x,dy=touch.clientY-heroTouchStart.y;heroTouchStart=null;if(Math.abs(dx)>50&&Math.abs(dx)>Math.abs(dy)*1.3)updateHero(heroIndex+(dx>0?1:-1))},{passive:true});
document.addEventListener('touchcancel',()=>{heroTouchStart=null},{passive:true});
setInterval(()=>{if(document.hidden||window.matchMedia('(prefers-reduced-motion: reduce)').matches||Date.now()-lastCarouselInteraction<9000)return;const hero=document.querySelector('.hero');if(hero&&!hero.matches(':hover')&&!hero.contains(document.activeElement))updateHero(heroIndex+1);const track=document.querySelector('.categories');if(track&&track.scrollWidth>track.clientWidth&&!track.matches(':hover')&&!track.contains(document.activeElement)){if(Math.abs(track.scrollLeft)>=track.scrollWidth-track.clientWidth-2)animateCategoryScroll(track,0);else moveCategories('next')}},6500);
